  "cursed magical stone": {"id": 6307, "atk": 0, "matk": 0, "def": 0, "weight": 0, "slots": 0, "wpnLvl": 0, "armLvl": 0, "minLvl": 0, "desc": "<span style=\"color:#ff0000\">This item cannot be traded with others.</span><br/><br/>Mineral with an odd pulse similar to the dimensional crack. You sense a magic that is not of this world from it."},
  "cursed ruby": {"id": 724, "atk": 0, "matk": 0, "def": 0, "weight": 100, "slots": 0, "wpnLvl": 0, "armLvl": 0, "minLvl": 0, "desc": "A ruby containing mysterious powers."},
