  "gigantic lance": {"id": 1490, "atk": 20, "matk": 0, "def": 0, "weight": 20000, "slots": 0, "wpnLvl": 4, "armLvl": 0, "minLvl": 140, "desc": "A replica spear of one held by the giant guardians at an ancient temple. Very few are able to use it's true power.<br/><br/><br/><br/>ASPD -10.<br/><br/>When unequipping, you lose 600 sp.<br/><br/>Increases cooldown time of <span style=\"color:#0000ff\">Spiral Pierce</span> by 20 seconds.<br/><br/><br/><br/>[<span style=\"color:#333399\">Base STR 120</span>]<br/><br/>ATK +300.<br/><br/><br/><br/><span style=\"color:#FF6600; margin-left: 10px;\"><b>"},
  "gigantic majestic goat": {"id": 5374, "atk": 0, "matk": 0, "def": 5, "weight": 800, "slots": 0, "wpnLvl": 0, "armLvl": 1, "minLvl": 0, "desc": "A headgear made from the horns of Baphomet. Increases physical damage to the Demi Human monster by 12%. As your JOB Level increases,the helm grants additional ATK."},
