  "safety helmet": {"id": 5009, "atk": 0, "matk": 0, "def": 3, "weight": 500, "slots": 0, "wpnLvl": 0, "armLvl": 1, "minLvl": 0, "desc": "A durable safety helmet created to offer some protection from accidents.<br/><br/>MDEF + 3<br/><br/>Indestructible (except in upgrade attempts)."},
  "safety knuckle": {"id": 1867, "atk": 210, "matk": 0, "def": 0, "weight": 1800, "slots": 2, "wpnLvl": 4, "armLvl": 0, "minLvl": 170, "desc": "It was designed for the safety of Einbech workers.<br/><br/>Due to its excellent durability, it was also improved for combat using various attachments.<br/><br/><br/><br/>ATK + 10%.<br/><br/>Increases damage of <span style=\"color:#009900\">Knuckle Arrow</span> by 10%.<br/><br/><br/><br/><span style=\"color:#0000FF\">Refine Level +7</span>:<br/><br/>ATK + 40, ASPD +15%.<br/><br/><br/><br/><span style=\"color:#0000FF\">Refine Level +9</span>:<br/><br/>Increases damage of <span style=\"color:#009900\">Knuckle Arrow</span> by additional 15%.<br/><br/>Physical attacks have a chance to increase physical damage to all size enemies by 15% for 10 seconds.<br/><br/><br/><br/><span style=\"color:#0000FF\">Refine Level +11</span>:<br/><br/>Decreases after skill delay of all skills by 20%."},
  "safety ring": {"id": 2615, "atk": 0, "matk": 0, "def": 3, "weight": 100, "slots": 0, "wpnLvl": 0, "armLvl": 1, "minLvl": 40, "desc": "A strange ring that curiously raises its wearer's defense.<br/><br/>MDEF + 3"},
