  "stalactic golem card": {"id": 4223, "atk": 0, "matk": 0, "def": 0, "weight": 10, "slots": 0, "wpnLvl": 0, "armLvl": 0, "minLvl": 0, "desc": "DEF + 1<br/><br/>Add a 20% resistance against <span style=\"color:#880000\">Stun</span>."},
