  "star crumb": {"id": 1000, "atk": 0, "matk": 0, "def": 0, "weight": 100, "slots": 0, "wpnLvl": 0, "armLvl": 0, "minLvl": 0, "desc": "A small stellar crystal, fallen from the heavens, which can be used to craft strengthened weapons."},
