  "steel chonchon egg": {"id": 9007, "atk": 0, "matk": 0, "def": 0, "weight": 0, "slots": 0, "wpnLvl": 0, "armLvl": 0, "minLvl": 0, "desc": "An egg in which a Steel Chonchon Cute Pet rests. Can be hatched by using a <span style=\"color:#33CC33\">Pet Incubator</span>.<br/><br/>FLEE + 6, AGI - 1."},
  "steel chonchon exchange ticket": {"id": 6167, "atk": 0, "matk": 0, "def": 0, "weight": 0, "slots": 0, "wpnLvl": 0, "armLvl": 0, "minLvl": 0, "desc": "A cute pet Steel Chonchon tickets."},
  "steel flower": {"id": 2687, "atk": 0, "matk": 0, "def": 1, "weight": 0, "slots": 0, "wpnLvl": 0, "armLvl": 1, "minLvl": 1, "desc": "<span style=\"color:blue\">Rental Items</span><br/><br/>A delicate flower that is placed in the mouth for romantic seduction.<br/><br/>Reduces damage from Plant monster by 3%.<br/><br/><br/><br/>Bonus : Autocasts <span style=\"color:#008800\">Level 1 Status Recovery</span> when the user receives Physical Damage."},
